import copy,hashlib,json,os,pathlib,subprocess,sys
ROOT=pathlib.Path('/Users/taylor/DevRepo/Skills/fsi-skills-library')
OUT=pathlib.Path('/tmp/payments-phase2-forward-governance')
PY='/tmp/fsi-p0-venv/bin/python'; ENV={**os.environ,'PYTHONDONTWRITEBYTECODE':'1'}
LOG=[]
SKILLS=['payment-regulatory-applicability-reviewer','payment-platform-architecture-reviewer','issuer-payment-dispute-reviewer']
def stable(x): return hashlib.sha256(json.dumps(x,sort_keys=True,separators=(',',':'),ensure_ascii=False,allow_nan=False).encode()).hexdigest()
def save(name,d):
 p=OUT/name;p.write_text(json.dumps(d,indent=2)+'\n');return p
sources={}
for skill in SKILLS:
 base=ROOT/'skills/payments'/skill
 for p in base.rglob('*'):
  if not p.is_file() or 'evals' in p.parts or p.name.startswith(('test','regression')) or p.suffix not in {'.md','.py','.json'}: continue
  sources[str(p.relative_to(ROOT))]=hashlib.sha256(p.read_bytes()).hexdigest()
save('source-sha256-before.json',sources)
def run(skill,script,inputpath,outputname=None,external=None):
 cmd=[PY,'-B',str(ROOT/'skills/payments'/skill/'scripts'/script),str(inputpath)]
 if external:cmd+=['--input',str(external)]
 r=subprocess.run(cmd,capture_output=True,text=True,env=ENV)
 LOG.append({'command':cmd,'exit_code':r.returncode,'stdout':r.stdout,'stderr':r.stderr})
 if outputname:(OUT/outputname).write_text(r.stdout)
 print(skill,script,inputpath.name,'EXIT',r.returncode,('saved '+outputname) if outputname else r.stdout.strip())
 save('execution-log.json',LOG)
 return r

def exercise(label,skill,data,phase2=True):
 ip=save(label+'-input.json',data);op=OUT/(label+'-output.json')
 run(skill,'validate_input.py',ip)
 result=run(skill,'calculate_or_transform.py',ip,op.name)
 if result.returncode==0:run(skill,'validate_output.py',op,external=ip if phase2 else None)
 return json.loads(result.stdout)

