 return {'schema_version':'1.0','request_id':ident,'as_of':'2026-09-18','jurisdiction':jur,'participant':participant,'requested_action':'analyze','sources':[{'source_id':x,'reference':'synthetic:'+x,'as_of':'2026-09-18','review_due':'2026-10-10'} for x in ['entity-doc','product-doc','funds-doc','architecture-doc','control-doc','migration-doc','specialist-doc']],'upstream_issues':[],'data':data}

