components=[{'component_id':i,'role':role,'owner':owner,'source_ids':['architecture-doc']} for i,role,owner in [('api','Accept client requests and correlate attempts','Channels'),('hub','Own instruction lifecycle and enforce one financial writer','Payments Engineering'),('ledger','Operational double-entry journal; does not establish rail finality','Finance Operations'),('network','Authoritative network status feed for rail acceptance and settlement','Network Operations'),('legacy','Existing legacy hub financial executor during migration','Payments Engineering')]]
