def controls(target):
 return {'idempotency':{'key_fields':['legal_entity_id','instruction_id'],'scope':'same legal entity and instruction across every retry/attempt','retention':'30 days and until all uncertain attempts resolve','atomic_enforcement':'Persist key+request digest atomically before dispatch; unique constraint on entity+instruction','payload_conflict_behavior':'reject-conflict','source_ids':['control-doc']},'uncertain_outcome':{'strategy':'status-then-reconcile','status_authority':'network','source_ids':['control-doc']},'reconciliation':{'source_component':'network','target_component':target,'partition_fields':['legal_entity_id','account_id','currency'],'match_keys':['instruction_id','network_payment_id'],'owner':'Payments Operations','exception_queue':'SYNTH-hub-unresolved','source_ids':['control-doc']}}
flows=[{'flow_id':'accept','stage':'initiation','from_component':'api','to_component':'hub','state_entity':'instruction','mutates_money':False,'source_ids':['architecture-doc']},{'flow_id':'submit','stage':'settlement','from_component':'hub','to_component':'network','state_entity':'network-payment','mutates_money':True,'source_ids':['architecture-doc'],**controls('hub')},{'flow_id':'book','stage':'posting','from_component':'hub','to_component':'ledger','state_entity':'ledger-entry','mutates_money':True,'source_ids':['architecture-doc'],'ledger_invariant':'Sum debit and credit per entity/currency = 0; corrections are linked compensating entries, no mutation of original posted rows.',**controls('ledger')},{'flow_id':'network-status','stage':'reconciliation','from_component':'network','to_component':'hub','state_entity':'network-payment','mutates_money':False,'source_ids':['architecture-doc']}]
archdata={'context':{'business_flow':'Bank outbound USD instant credit transfers through hub into rail with operational journal and independent network status.','current_constraint':'Current API retries on timeout, sometimes with a new attempt ID; network outcome can be unknown.','target_outcome':'Reduce uncertain duplicate attempts while preserving traceable rail and ledger outcomes.','module':'hub','source_ids':['architecture-doc']},'components':components,'data_models':models,'flows':flows,'nfrs':[{'nfr_id':'availability','metric':'availability','target':'99.95','unit':'percent','measurement_plan':'Measure valid request availability per minute and report monthly, including controlled dependency failure drills.','owner':'SRE','source_ids':['control-doc']},{'nfr_id':'uncertain-age','metric':'maximum-uncertain-age','target':'15','unit':'minutes','measurement_plan':'Inject ambiguous network timeout; alert queue owner after 15 minutes and reconcile against status journal.','owner':'Payments Operations','source_ids':['control-doc']}],'options':[{'option_id':'retain','description':'Keep legacy executor and add durable deduplication/status polling','component_changes':['legacy deduplication store','network status adapter'],'benefits':['Small cutover scope'],'tradeoffs':['Legacy coupling remains'],'acceptance_evidence':['synthetic legacy adapter design; fault-injection results still required'],'source_ids':['architecture-doc']},{'option_id':'strangler','description':'Strangler migration with new hub orchestration and one executor per partition','component_changes':['hub instruction state store','atomic writer-ownership registry','network status adapter'],'benefits':['Explicit uncertain state and partition ownership'],'tradeoffs':['Extra transition complexity; dual schemas during migration'],'acceptance_evidence':['synthetic design review; end-to-end test and reconciliation evidence required before cutover'],'source_ids':['architecture-doc']}],'migration':[{'phase_id':'shadow','sequence':1,'scope':'Read-only shadow only; legacy retains sole financial execution','entry_evidence':['approved mapping specification','synthetic masked replay corpus'],'exit_evidence':['all test events mapped with explainable differences','zero financial writes by shadow'],'inflight_handling':'Legacy owns all active instructions to terminal reconciliation; shadow only observes','financial_reconciliation':'Match network status, instruction record and journal by entity/account/currency and instruction','rollback_boundary':'Disable shadow intake without changing any accepted payment','rollback_mode':'stop-new-intake','dual_financial_execution':False,'owner':'Payments Engineering','source_ids':['migration-doc']},{'phase_id':'canary','sequence':2,'scope':'5% canary of newly accepted instructions in disjoint ownership partition','entry_evidence':['reconciliation gate signed by Operations','timeout/payload-conflict/replay test report','atomic writer fencing verified'],'exit_evidence':['zero unexplained unmatched payments for five working days','NFR results and on-call exercise accepted'],'inflight_handling':'Ownership registry assigns exactly one executor at initial acceptance; old in-flight stays legacy until reconciled','financial_reconciliation':'Network-to-hub-to-journal counts and amount balances plus exception review per partition before expansion','rollback_boundary':'Stop routing new instructions to canary; retain its accepted/in-flight ownership until reconciled; no automatic reversal of settled funds','rollback_mode':'stop-new-intake','dual_financial_execution':False,'owner':'Payments Engineering','source_ids':['migration-doc']}]}
